import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Installing Business Central from the Microsoft Installation Kit","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/installing-business-central-from-microsoft-installation-kit.md","filePath":"installation-and-setup/installing-business-central-from-microsoft-installation-kit.md"}`),a={name:`installation-and-setup/installing-business-central-from-microsoft-installation-kit.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="installing-business-central-from-the-microsoft-installation-kit" tabindex="-1">Installing Business Central from the Microsoft Installation Kit <a class="header-anchor" href="#installing-business-central-from-the-microsoft-installation-kit" aria-label="Permalink to “Installing Business Central from the Microsoft Installation Kit”">​</a></h1><p>This method installs Business Central directly on Windows using Microsoft&#39;s installation media, rather than running it inside a Docker container.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before starting, ensure that you have:</p><ul><li><strong>SQL Server:</strong> Installed with the <strong>Full-Text and Semantic Extractions for Search</strong> feature enabled. This is required for installing the CRONUS demonstration database.</li><li><strong>SQL Server service:</strong> Running so that the Business Central installer can connect to the database engine.</li><li><strong>TCP/IP:</strong> Enabled in SQL Server Configuration Manager under <em>SQL Server Network Configuration → Protocols for MSSQLSERVER</em>.</li><li><strong>Administrator privileges:</strong> Required to run the installer and configure Windows components.</li></ul><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to “Installation Steps”">​</a></h2><h3 id="step-1-download-the-installation-kit" tabindex="-1">Step 1: Download the Installation Kit <a class="header-anchor" href="#step-1-download-the-installation-kit" aria-label="Permalink to “Step 1: Download the Installation Kit”">​</a></h3><p>Visit the Microsoft update page for <a href="https://support.microsoft.com/en-us/servicing/dynamics/business-central/update/2026/10/update-27-12-for-microsoft-dynamics-365-business-central-2025-release-wave-2" target="_blank" rel="noreferrer">Update 27.12 for Microsoft Dynamics 365 Business Central, 2025 release wave 2</a>.</p><p>Scroll to the list of countries and select <strong>All other countries/regions</strong>.</p><p>Alternatively, download the worldwide (<code>W1</code>) installation kit directly:</p><p><a href="https://download.microsoft.com/download/c6a26592-375f-4768-89ca-f37ed4ab9342/Dynamics.365.BC.55425.W1.DVD.zip" target="_blank" rel="noreferrer">Download Business Central Installation Kit (W1)</a></p><h3 id="step-2-extract-the-files" tabindex="-1">Step 2: Extract the Files <a class="header-anchor" href="#step-2-extract-the-files" aria-label="Permalink to “Step 2: Extract the Files”">​</a></h3><ol><li>Extract the downloaded ZIP file to a folder on your computer.</li><li>Locate <code>setup.exe</code> in the extracted files.</li><li>Right-click <code>setup.exe</code> and select <strong>Run as administrator</strong>.</li></ol><h3 id="step-3-select-the-installation-options" tabindex="-1">Step 3: Select the Installation Options <a class="header-anchor" href="#step-3-select-the-installation-options" aria-label="Permalink to “Step 3: Select the Installation Options”">​</a></h3><p>Follow the installation wizard:</p><ol><li>On the first screen, select <strong>Advanced installation options</strong>, then click <strong>Next</strong>.</li></ol><p><img src="/installation-screen-1.png" alt="Screen 1" width="901" height="769"></p><ol start="2"><li>On the next screen, select <strong>Choose an installation option</strong>, then click <strong>Next</strong>.</li></ol><p><img src="/installation-screen-2.png" alt="Screen 2" width="895" height="765"></p><ol start="3"><li>Select <strong>Developer</strong>, then click <strong>Next</strong>.</li></ol><p><img src="/installation-screen-3.png" alt="Screen 3" width="889" height="762"></p><ol start="4"><li>Finally, click <strong>Apply</strong> to begin installation.</li></ol><p><img src="/installation-screen-4.png" alt="Screen 4" width="890" height="770"></p><h3 id="step-4-verify-that-the-business-central-server-is-running" tabindex="-1">Step 4: Verify That the Business Central Server Is Running <a class="header-anchor" href="#step-4-verify-that-the-business-central-server-is-running" aria-label="Permalink to “Step 4: Verify That the Business Central Server Is Running”">​</a></h3><p>The Business Central Server service runs the application’s core server components. Before accessing the web client, verify that this service is running.</p><ol><li>Press <strong><code>Win + R</code></strong> to open the Run dialog.</li><li>Enter <code>services.msc</code> and press <strong>Enter</strong>.</li><li>Locate <strong>Microsoft Dynamics 365 Business Central Server [BC270]</strong> in the list of services.</li><li>Check the <strong>Status</strong> column. If the service is not running, right-click it and select <strong>Start</strong>.</li></ol><h3 id="step-5-open-the-business-central-web-client" tabindex="-1">Step 5: Open the Business Central Web Client <a class="header-anchor" href="#step-5-open-the-business-central-web-client" aria-label="Permalink to “Step 5: Open the Business Central Web Client”">​</a></h3><p>The Business Central web client is hosted in Internet Information Services (IIS), which allows you to access Business Central through a web browser.</p><ol><li>Open Windows Search and search for <strong>Internet Information Services (IIS) Manager</strong>.</li><li>Launch IIS Manager.</li><li>In the <strong>Connections</strong> pane on the left, expand your computer name, then expand <strong>Sites</strong>.</li><li>Locate <strong>Microsoft Dynamics 365 Business Central Web Client</strong> and expand it.</li><li>Find the <strong>BC270</strong> application, right-click it, and select <strong>Manage Application → Browse</strong>.</li><li>Your default web browser should open the Business Central web client.</li></ol><h2 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to “Additional Resources”">​</a></h2><ul><li><a href="https://support.microsoft.com/en-us/servicing/dynamics/business-central/update/2026/10/update-27-12-for-microsoft-dynamics-365-business-central-2025-release-wave-2" target="_blank" rel="noreferrer">Microsoft Business Central update and download information</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-dev-overview" target="_blank" rel="noreferrer">Business Central developer documentation</a></li><li><a href="https://learn.microsoft.com/en-us/sql/database-engine/configure-windows/enable-or-disable-a-server-network-protocol" target="_blank" rel="noreferrer">Microsoft documentation: Enable or disable a SQL Server network protocol</a></li></ul>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};